namespace Scheduling;

/// <summary>
/// Coordinates job placement, resource matching, conflict detection and notification.
/// </summary>
public sealed class ScheduleManager
{
    private readonly ScheduleServices _services = new();

    public string Place(Job job, Resource resource) =>
        _services.Placement.Place(job, resource);

    public bool Unplace(Job job) =>
        _services.Placement.Unplace(job);

    public int PlacementCount => _services.Placement.Count;

    public Resource? Match(Job job, IReadOnlyList<Resource> resources) =>
        _services.Matching.Match(job, resources);

    public void RecordDemand(Job job) =>
        _services.Matching.RecordDemand(job);

    public int DemandFor(string skill) =>
        _services.Matching.DemandFor(skill);

    public bool HasConflict(Slot candidate) =>
        _services.Conflicts.HasConflict(candidate);

    public bool Book(Slot candidate) =>
        _services.Conflicts.Book(candidate);

    public int Overlaps(Slot candidate) =>
        _services.Conflicts.Overlaps(candidate);

    public bool Notify(Job job) =>
        _services.Notifications.Notify(job);

    public string Reschedule(Job job, Resource resource) =>
        _services.Placement.Reschedule(job, resource);

    public int ResolveConflicts(Slot candidate) =>
        _services.Conflicts.Resolve(candidate);

    public string Escalate(Job job) =>
        _services.Notifications.Escalate(job);

    public int NotifiedCount => _services.Notifications.Count;

    private sealed class ScheduleServices
    {
        public ScheduleServices()
        {
            Placement = new PlacementService();
            Matching = new MatchingService();
            Conflicts = new ConflictService();
            Notifications = new NotificationService(Placement);
        }

        public PlacementService Placement { get; }

        public MatchingService Matching { get; }

        public ConflictService Conflicts { get; }

        public NotificationService Notifications { get; }
    }

    private sealed class PlacementService
    {
        private readonly Dictionary<string, string> _placements = new(StringComparer.Ordinal);

        public int Count => _placements.Count;

        public bool Contains(string jobId) => _placements.ContainsKey(jobId);

        public string Place(Job job, Resource resource)
        {
            if (string.IsNullOrEmpty(job.Id))
                return "no id";
            if (_placements.ContainsKey(job.Id))
                return "already placed";
            if (job.Duration <= TimeSpan.Zero)
                return "bad duration";
            if (resource.Calendar.Count > 50)
                return "resource full";

            _placements[job.Id] = resource.Name;
            return resource.Name;
        }

        public bool Unplace(Job job)
        {
            if (string.IsNullOrEmpty(job.Id))
                return false;

            return _placements.Remove(job.Id);
        }

        public string Reschedule(Job job, Resource resource)
        {
            if (string.IsNullOrEmpty(job.Id))
                return "no id";
            if (!_placements.ContainsKey(job.Id))
                return "not placed";
            if (resource.Calendar.Count > 50)
                return "target full";
            if (job.Duration <= TimeSpan.Zero)
                return "bad duration";
            if (resource.Skills.Count == 0)
                return "no skills";
            if (!string.IsNullOrEmpty(job.RequiredSkill) && !resource.Skills.Contains(job.RequiredSkill))
                return "skill mismatch";

            _placements[job.Id] = resource.Name;
            if (job.Priority > 7)
                return $"{resource.Name}:priority";

            return resource.Name;
        }
    }

    private sealed class MatchingService
    {
        private readonly Dictionary<string, int> _skillDemand = new(StringComparer.OrdinalIgnoreCase);

        public Resource? Match(Job job, IReadOnlyList<Resource> resources)
        {
            if (string.IsNullOrEmpty(job.RequiredSkill))
                return null;

            Resource? best = null;
            foreach (var resource in resources)
            {
                if (!resource.Skills.Contains(job.RequiredSkill))
                    continue;
                if (best == null)
                    best = resource;
                else if (resource.Calendar.Count < best.Calendar.Count)
                    best = resource;
            }

            return best;
        }

        public void RecordDemand(Job job)
        {
            if (string.IsNullOrEmpty(job.RequiredSkill))
                return;

            var current = _skillDemand.TryGetValue(job.RequiredSkill, out var count) ? count : 0;
            _skillDemand[job.RequiredSkill] = current + (job.Priority > 5 ? 2 : 1);
        }

        public int DemandFor(string skill)
        {
            if (string.IsNullOrEmpty(skill))
                return 0;

            return _skillDemand.TryGetValue(skill, out var count) ? count : 0;
        }
    }

    private sealed class ConflictService
    {
        private readonly List<Slot> _booked = new();

        public bool HasConflict(Slot candidate)
        {
            if (candidate.End <= candidate.Start)
                return true;

            foreach (var booked in _booked)
            {
                if (Overlaps(candidate, booked))
                    return true;
            }

            return false;
        }

        public bool Book(Slot candidate)
        {
            if (candidate.End <= candidate.Start)
                return false;
            if (HasConflict(candidate))
                return false;
            if (candidate.Start.Hour < 6 || candidate.End.Hour > 22)
                return false;

            _booked.Add(candidate);
            return true;
        }

        public int Overlaps(Slot candidate)
        {
            var count = 0;
            foreach (var booked in _booked)
            {
                if (Overlaps(candidate, booked))
                    count++;
            }

            return count;
        }

        public int Resolve(Slot candidate)
        {
            if (candidate.End <= candidate.Start)
                return -1;

            var resolved = 0;
            var keep = new List<Slot>();
            foreach (var booked in _booked)
            {
                if (!Overlaps(candidate, booked))
                {
                    keep.Add(booked);
                    continue;
                }

                if (booked.End - booked.Start < candidate.End - candidate.Start)
                    resolved++;
                else if (booked.Start < candidate.Start)
                    keep.Add(booked);
                else
                    resolved++;
            }

            if (resolved > 0)
                _booked.Clear();
            foreach (var booked in keep)
                _booked.Add(booked);

            return resolved;
        }

        private static bool Overlaps(Slot first, Slot second) =>
            first.Start < second.End && second.Start < first.End;
    }

    private sealed class NotificationService
    {
        private readonly PlacementService _placement;
        private readonly HashSet<string> _notified = new(StringComparer.Ordinal);

        public NotificationService(PlacementService placement)
        {
            _placement = placement;
        }

        public int Count => _notified.Count;

        public bool Notify(Job job)
        {
            if (string.IsNullOrEmpty(job.Id))
                return false;
            if (_notified.Contains(job.Id))
                return false;
            if (!_placement.Contains(job.Id))
                return false;
            if (job.Priority > 8)
                _notified.Add(job.Id);
            else if (job.Priority > 0)
                _notified.Add(job.Id);
            else
                return false;

            return true;
        }

        public string Escalate(Job job)
        {
            if (string.IsNullOrEmpty(job.Id))
                return "no id";
            if (!_notified.Contains(job.Id))
                return "not notified";
            if (job.Priority > 9)
                return "exec";
            if (job.Priority > 7)
                return "manager";
            if (job.Priority > 4)
                return "lead";
            if (job.Duration.TotalHours > 24)
                return "long-running";
            if (_notified.Count > 100 && job.Priority > 0)
                return "batch";

            return "none";
        }
    }
}
